export const HALL_GAMES=[['baseball','야구공 게임'],['2048','2048'],['solitaire','솔리테어'],['snake','스네이크']];
const trophy='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v3h4v3a5 5 0 0 1-5 5 5 5 0 0 1-3 2v3h4v2H7v-2h4v-3a5 5 0 0 1-3-2 5 5 0 0 1-5-5V6h4V3zm0 5H5v1a3 3 0 0 0 2 3V8zm10 0v4a3 3 0 0 0 2-3V8z"/></svg>';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const monthValid=m=>typeof m==='string'&&/^\d{4}-(0[1-9]|1[0-2])-01$/.test(m)&&m>='2026-10-01';
export const hallRound=m=>(Number(m.slice(0,4))-2026)*12+Number(m.slice(5,7))-9;
const monthLabel=m=>Number(m.slice(0,4))+'년 '+Number(m.slice(5,7))+'월';
const number=new Intl.NumberFormat('ko-KR'),compact=new Intl.NumberFormat('ko-KR',{notation:'compact',maximumFractionDigits:1});
const score=s=>(s<1000000?number:compact).format(s),time=ms=>{const s=Math.floor(ms/1000);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');};
function entryValid(e){return e&&HALL_GAMES.some(([key])=>key===e.game)&&typeof e.name==='string'&&e.name.trim()&&e.name.length<=80&&Number.isSafeInteger(e.score)&&e.score>=0&&e.score<=2000000000&&(e.elapsedMs===null||e.elapsedMs===undefined||Number.isSafeInteger(e.elapsedMs)&&e.elapsedMs>=0);}
export function normalizeHall(data){const months=new Map();for(const m of Array.isArray(data?.months)?data.months:[]){if(!monthValid(m?.month))continue;const used=new Set(),entries=(Array.isArray(m.entries)?m.entries:[]).filter(e=>{if(!entryValid(e)||!Number.isInteger(e.place)||e.place<1||e.place>3)return false;const key=e.game+':'+e.place;if(used.has(key))return false;used.add(key);return true;});months.set(m.month,{month:m.month,finalized:m.finalized===true,entries});}return{months:[...months.values()].sort((a,b)=>b.month.localeCompare(a.month)),records:(Array.isArray(data?.records)?data.records:[]).filter(entryValid),serverNow:Number(data?.serverNow),resetsAt:Number(data?.resetsAt)};}
function details(e){return number.format(e.score)+'점'+(Number.isSafeInteger(e.elapsedMs)?' · '+time(e.elapsedMs):'');}
function podium(key,label,entries){const slots=[1,2,3].map(place=>{const e=entries.find(e=>e.game===key&&e.place===place);return`<li class="hof-place${e?'':' hof-vacant'}" data-place="${place}" aria-label="${place}위${e?' '+esc(e.name)+', '+esc(details(e)):' 기록 없음'}"><span class="hof-name" title="${esc(e?.name||'')}">${e?esc(e.name):'기록 없음'}</span><span class="hof-block"><span class="hof-trophy">${trophy}</span></span><span class="hof-score" title="${e?esc(details(e)):''}">${e?score(e.score)+'점':'—'}</span></li>`;}).join('');return`<article class="hof-game"><h3>${label}</h3><ol class="hof-podium" aria-label="${label} 월간 1~3위">${slots}</ol></article>`;}
function recordCard(key,label,records){const e=records.find(e=>e.game===key);let date='';if(e?.achievedAt&&Number.isFinite(Date.parse(e.achievedAt)))date=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(e.achievedAt));return`<article class="hof-record${e?'':' hof-record-empty'}"><h3>${label}</h3><span class="hof-record-name" title="${esc(e?.name||'')}">${e?esc(e.name):'기록 없음'}</span><span class="hof-trophy" data-place="1">${trophy}</span><strong title="${e?esc(details(e)):''}">${e?score(e.score)+'점':'—'}</strong><small>${date||'아직 등록된 기록이 없습니다.'}${Number.isSafeInteger(e?.elapsedMs)?' · '+time(e.elapsedMs):''}</small></article>`;}
export function hallMarkup(data){const hall=normalizeHall(data);return`<div class="hof-months">${hall.months.map(m=>`<section class="hof-month" aria-label="${monthLabel(m.month)} 월간 명예의 전당"><header class="hof-month-heading"><span class="hof-round">[${hallRound(m.month)}회차]</span><h2>${monthLabel(m.month)}</h2>${m.finalized?'':'<span class="hof-live">집계 중</span>'}</header><div class="hof-game-grid">${HALL_GAMES.map(([key,label])=>podium(key,label,m.entries)).join('')}</div></section>`).join('')}</div><section class="hof-records" aria-labelledby="hof-records-heading"><h2 id="hof-records-heading">역대 최고 기록</h2><div class="hof-game-grid">${HALL_GAMES.map(([key,label])=>recordCard(key,label,hall.records)).join('')}</div></section>`;}
export async function renderHallOfFame(main,{db,signal,isCurrent=()=>true}={}){
 const alive=()=>!signal?.aborted&&isCurrent();if(!alive())return;main.innerHTML='<div class="hall-page"><header class="hall-heading"><h1>명예의 전당</h1></header><div id="hall-content" aria-live="polite"><div class="loading">기록을 불러오고 있어요.</div></div></div>';const content=main.querySelector('#hall-content');let request=0,interval=0,monthTimer=0,deadline=0;
 function armMonth(){clearTimeout(monthTimer);if(!alive()||!deadline)return;monthTimer=setTimeout(()=>{if(Date.now()<deadline)armMonth();else void refresh();},Math.min(2147483647,Math.max(0,deadline-Date.now())));}
 async function refresh(){const id=++request;try{const{data,error}=await db.rpc('get_game_hall_of_fame');if(!alive()||id!==request)return;if(error||!data)throw Error();const normalized=normalizeHall(data);content.innerHTML=hallMarkup(data);if(Number.isFinite(normalized.serverNow)&&normalized.resetsAt>normalized.serverNow){deadline=Date.now()+normalized.resetsAt-normalized.serverNow;armMonth();}}catch{if(alive()&&id===request&&!content.querySelector('.hof-months')){content.innerHTML='<div class="hof-error"><p>기록을 불러오지 못했어요.</p><button type="button" class="secondary">다시 시도</button></div>';content.querySelector('button').onclick=()=>void refresh();}}}
 const onVisible=()=>{if(!document.hidden)void refresh();};document.addEventListener('visibilitychange',onVisible);signal?.addEventListener('abort',()=>{clearInterval(interval);clearTimeout(monthTimer);document.removeEventListener('visibilitychange',onVisible);},{once:true});await refresh();if(alive())interval=setInterval(()=>{if(!document.hidden)void refresh();},30000);
}
